const plugins = new Map();
export async function loadPlugin(specifier, ctx) {
  const mod = await import(specifier);            // "my-plugin" or a file URL
  const plugin = mod.default ?? mod;
  if (typeof plugin.setup !== "function") throw new Error(`invalid plugin: ${specifier}`);
  plugins.set(plugin.name, plugin);
  await plugin.setup(ctx);
  return plugin;
}
